using FinanceInzicht.Domain; using Microsoft.EntityFrameworkCore;
namespace FinanceInzicht.Infrastructure;
public sealed class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){public DbSet<ImportFile> ImportFiles=>Set<ImportFile>();public DbSet<ImportJob> ImportJobs=>Set<ImportJob>();public DbSet<BankAccount> BankAccounts=>Set<BankAccount>();public DbSet<BankStatement> BankStatements=>Set<BankStatement>();public DbSet<BankTransaction> BankTransactions=>Set<BankTransaction>();public DbSet<ImportWarning> ImportWarnings=>Set<ImportWarning>();public DbSet<TransactionLabel> TransactionLabels=>Set<TransactionLabel>();public DbSet<CounterpartyCategoryRule> CounterpartyCategoryRules=>Set<CounterpartyCategoryRule>(); protected override void OnModelCreating(ModelBuilder b){b.HasPostgresExtension("pgcrypto"); foreach(var e in b.Model.GetEntityTypes())e.SetTableName(ToSnake(e.GetTableName()!)); foreach(var p in b.Model.GetEntityTypes().SelectMany(x=>x.GetProperties()))p.SetColumnName(ToSnake(p.Name)); b.Entity<TransactionLabel>().HasIndex(x=>x.BankTransactionId).IsUnique();b.Entity<CounterpartyCategoryRule>().HasIndex(x=>x.CounterpartyIban).IsUnique();b.Entity<ImportFile>().HasIndex(x=>x.Sha256).IsUnique(); b.Entity<ImportJob>().HasIndex(x=>new{x.Status,x.CreatedAtUtc}); b.Entity<BankAccount>().HasIndex(x=>x.Iban).IsUnique(); b.Entity<BankStatement>().HasIndex(x=>new{x.BankAccountId,x.StatementId}).IsUnique(); b.Entity<BankStatement>().Property(x=>x.RawStatementJson).HasColumnType("jsonb"); b.Entity<BankTransaction>().HasIndex(x=>x.Fingerprint).IsUnique();b.Entity<BankTransaction>().HasIndex(x=>new{x.BankAccountId,x.BookingDate});b.Entity<BankTransaction>().HasIndex(x=>x.CounterpartyIban);b.Entity<BankTransaction>().HasIndex(x=>x.AccountServicerReference);b.Entity<BankTransaction>().HasIndex(x=>x.EndToEndId);b.Entity<BankTransaction>().Property(x=>x.RawEntryJson).HasColumnType("jsonb");} static string ToSnake(string s)=>string.Concat(s.Select((c,i)=>char.IsUpper(c)&&i>0?"_"+char.ToLowerInvariant(c):char.ToLowerInvariant(c).ToString()));}
